const staticData = $getWorkflowStaticData('global');
if (!staticData.guardrails) staticData.guardrails = [];
if (!staticData.gr_documents) staticData.gr_documents = [];
if (!staticData.next_gr_id) staticData.next_gr_id = 1;
if (!staticData.next_gr_doc_id) staticData.next_gr_doc_id = 1;

const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;
const action = body.action || 'ping';

function now() { return new Date().toISOString(); }
let result = {};

switch (action) {
  case 'ping':
    result = { ok: true, message: 'Guardrails Manager webhook reachable', received_at: now() };
    break;
  case 'create_guardrail': {
    const name = (body.name || '').trim();
    if (!name) { result = { error: 'Guardrail name is required.' }; break; }
    const gr = { id: staticData.next_gr_id++, name, description: (body.description || '').trim(), created_at: now() };
    staticData.guardrails.push(gr);
    result = { ok: true, guardrail: gr };
    break;
  }
  case 'list_guardrails': {
    const grs = staticData.guardrails.map(gr => {
      const docCount = staticData.gr_documents.filter(d => d.gr_id === gr.id).length;
      return { ...gr, doc_count: docCount };
    });
    result = { guardrails: grs };
    break;
  }
  case 'delete_guardrail': {
    const grId = parseInt(body.guardrail_id);
    if (!grId) { result = { error: 'guardrail_id is required.' }; break; }
    const idx = staticData.guardrails.findIndex(g => g.id === grId);
    if (idx === -1) { result = { error: 'Guardrail not found.' }; break; }
    staticData.guardrails.splice(idx, 1);
    staticData.gr_documents = staticData.gr_documents.filter(d => d.gr_id !== grId);
    result = { ok: true };
    break;
  }
  case 'upload_doc': {
    const grId = parseInt(body.guardrail_id);
    if (!grId) { result = { error: 'guardrail_id is required.' }; break; }
    const gr = staticData.guardrails.find(g => g.id === grId);
    if (!gr) { result = { error: 'Guardrail not found.' }; break; }
    const filename = (body.filename || '').trim();
    if (!filename) { result = { error: 'filename is required.' }; break; }
    const content = (body.content || '').trim();
    if (!content) { result = { error: 'content is required.' }; break; }
    const docCount = staticData.gr_documents.filter(d => d.gr_id === grId).length;
    if (docCount >= 20) { result = { error: 'Max 20 documents per guardrail.' }; break; }
    const doc = { id: staticData.next_gr_doc_id++, gr_id: grId, filename, content, file_size: parseInt(body.file_size) || content.length, uploaded_at: now() };
    staticData.gr_documents.push(doc);
    result = { ok: true, document: { id: doc.id, filename: doc.filename, file_size: doc.file_size } };
    break;
  }
  case 'list_docs': {
    const grId = parseInt(body.guardrail_id);
    if (!grId) { result = { error: 'guardrail_id is required.' }; break; }
    const docs = staticData.gr_documents.filter(d => d.gr_id === grId).map(d => ({ id: d.id, filename: d.filename, file_size: d.file_size, uploaded_at: d.uploaded_at }));
    result = { documents: docs };
    break;
  }
  case 'delete_doc': {
    const grId = parseInt(body.guardrail_id);
    const docId = parseInt(body.doc_id);
    if (!grId || !docId) { result = { error: 'guardrail_id and doc_id are required.' }; break; }
    const idx = staticData.gr_documents.findIndex(d => d.id === docId && d.gr_id === grId);
    if (idx === -1) { result = { error: 'Document not found.' }; break; }
    staticData.gr_documents.splice(idx, 1);
    result = { ok: true };
    break;
  }
  case 'get_content': {
    const grId = parseInt(body.guardrail_id);
    if (!grId) { result = { error: 'guardrail_id is required.' }; break; }
    const gr = staticData.guardrails.find(g => g.id === grId);
    if (!gr) { result = { error: 'Guardrail not found.' }; break; }
    const docs = staticData.gr_documents.filter(d => d.gr_id === grId);
    const text = docs.map(d => '## ' + d.filename + '\n\n' + d.content).join('\n\n---\n\n');
    result = { guardrail_id: grId, guardrail_name: gr.name, content: text, doc_count: docs.length };
    break;
  }
  default:
    result = { error: 'Unknown action: ' + action };
}
return [{ json: result }];
